PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
PRAGMA busy_timeout=5000;
CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT OR IGNORE INTO migrations VALUES(1,datetime('now'));
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS raw_fetches(id TEXT PRIMARY KEY, resource TEXT NOT NULL, provider TEXT NOT NULL, requested_at TEXT NOT NULL, received_at TEXT NOT NULL, expires_at TEXT NOT NULL, source TEXT NOT NULL, body_hash TEXT NOT NULL, body TEXT NOT NULL, imported INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS raw_resource ON raw_fetches(resource,received_at);
CREATE TABLE IF NOT EXISTS usage(id INTEGER PRIMARY KEY, day TEXT NOT NULL, month TEXT NOT NULL, provider TEXT NOT NULL, reserved INTEGER NOT NULL, charged INTEGER, state TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS teams(id TEXT PRIMARY KEY, name TEXT NOT NULL, conference TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS aliases(alias TEXT NOT NULL, team_id TEXT NOT NULL REFERENCES teams(id), PRIMARY KEY(alias,team_id));
CREATE TABLE IF NOT EXISTS games(id TEXT PRIMARY KEY, provider_id TEXT NOT NULL UNIQUE, home_id TEXT NOT NULL REFERENCES teams(id), away_id TEXT NOT NULL REFERENCES teams(id), kickoff TEXT NOT NULL, season INTEGER NOT NULL, conference TEXT, completed INTEGER NOT NULL, status TEXT NOT NULL, raw_id TEXT REFERENCES raw_fetches(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS event_links(event_id TEXT PRIMARY KEY, game_id TEXT NOT NULL REFERENCES games(id), observed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quarantined_events(id TEXT PRIMARY KEY, observed_at TEXT NOT NULL, reason TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS odds(id TEXT PRIMARY KEY, raw_id TEXT NOT NULL REFERENCES raw_fetches(id), game_id TEXT NOT NULL REFERENCES games(id), book TEXT NOT NULL, book_name TEXT NOT NULL, market TEXT NOT NULL, side TEXT NOT NULL, line REAL, price REAL NOT NULL, quoted_at TEXT, observed_at TEXT NOT NULL, imported INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS odds_history ON odds(game_id,market,book,observed_at,quoted_at);
CREATE TABLE IF NOT EXISTS snapshots(id TEXT PRIMARY KEY, at TEXT NOT NULL, raw_ids TEXT NOT NULL, data TEXT NOT NULL, imported INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS model_registry(version TEXT PRIMARY KEY, artifact_hash TEXT NOT NULL, activated_at TEXT NOT NULL, state TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS predictions(id TEXT PRIMARY KEY, game_id TEXT NOT NULL REFERENCES games(id), market TEXT NOT NULL, version TEXT NOT NULL, artifact_hash TEXT NOT NULL, snapshot_id TEXT NOT NULL REFERENCES snapshots(id), issued_at TEXT NOT NULL, kickoff TEXT NOT NULL, data TEXT NOT NULL, UNIQUE(game_id,market,version));
CREATE TABLE IF NOT EXISTS decisions(id TEXT PRIMARY KEY, at TEXT NOT NULL, snapshot_id TEXT NOT NULL, game_id TEXT NOT NULL, market TEXT NOT NULL, policy TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audits(id TEXT PRIMARY KEY, prediction_id TEXT, at TEXT NOT NULL, result TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settlements(id TEXT PRIMARY KEY, prediction_id TEXT NOT NULL REFERENCES predictions(id), observed_at TEXT NOT NULL, result TEXT NOT NULL, profit REAL NOT NULL, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS settlement_prediction ON settlements(prediction_id,observed_at);
CREATE TABLE IF NOT EXISTS feature_snapshots(id TEXT PRIMARY KEY, game_id TEXT NOT NULL, cutoff TEXT NOT NULL, source_ids TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs(id INTEGER PRIMARY KEY, started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL, details TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS simulations(id TEXT PRIMARY KEY, game_id TEXT NOT NULL, version TEXT NOT NULL, at TEXT NOT NULL, data TEXT NOT NULL);
INSERT OR IGNORE INTO migrations VALUES(2,datetime('now'));
CREATE TABLE IF NOT EXISTS ai_opinions(id TEXT PRIMARY KEY, game_id TEXT NOT NULL REFERENCES games(id), market TEXT NOT NULL, version TEXT NOT NULL, generated_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_settlements(id TEXT PRIMARY KEY, opinion_id TEXT NOT NULL REFERENCES ai_opinions(id), observed_at TEXT NOT NULL, result TEXT NOT NULL, profit REAL NOT NULL);
INSERT OR IGNORE INTO migrations VALUES(3,datetime('now'));
CREATE TABLE IF NOT EXISTS usage_notes(id TEXT PRIMARY KEY, usage_id INTEGER NOT NULL, at TEXT NOT NULL, note TEXT NOT NULL);
INSERT OR IGNORE INTO migrations VALUES(4,datetime('now'));
CREATE TABLE IF NOT EXISTS research_reviews(id TEXT PRIMARY KEY, game_id TEXT NOT NULL, fingerprint TEXT NOT NULL, reviewer TEXT NOT NULL, generated_at TEXT NOT NULL, expires_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS research_current ON research_reviews(game_id,fingerprint,generated_at);
CREATE TABLE IF NOT EXISTS research_jobs(id TEXT PRIMARY KEY, game_id TEXT NOT NULL, fingerprint TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, lease_until TEXT, error TEXT, UNIQUE(game_id,fingerprint));
CREATE TABLE IF NOT EXISTS ai_usage(id TEXT PRIMARY KEY, day TEXT NOT NULL, at TEXT NOT NULL, state TEXT NOT NULL, model TEXT NOT NULL, input_tokens INTEGER, output_tokens INTEGER, response_id TEXT);
INSERT OR IGNORE INTO migrations VALUES(5,datetime('now'));
CREATE TABLE IF NOT EXISTS weather_cache(venue_id TEXT PRIMARY KEY, raw_id TEXT NOT NULL REFERENCES raw_fetches(id), forecast_index INTEGER NOT NULL, expires_at TEXT NOT NULL);
INSERT OR IGNORE INTO migrations VALUES(6,datetime('now'));
